// Connection The last will message of the mobile robot. Has to be sent with retain flag. Once the
// mobile robot comes online, it has to send this message on its connect topic, with the
// connectionState enum set to "ONLINE". The last will message is to be configured with the
// connection state set to "CONNECTION_BROKEN". Thus, if the mobile robot disconnects from the
// broker, fleet control gets notified via the topic "connection". If the mobile robot is
// disconnecting in an orderly fashion (e.g. shutting down, sleeping), the mobile robot is to
// publish a message on this topic with the connectionState set to "OFFLINE".
type Connection struct {
	// Header ID of the message. The headerId is defined per topic and incremented by 1 with each sent
	// (but not necessarily received) message.
	HeaderID uint32 `json:"headerId"`
	// Timestamp in ISO8601 format (YYYY-MM-DDTHH:mm:ss.fffZ).
	Timestamp string `json:"timestamp"`
	// Version of the protocol [Major].[Minor].[Patch]
	Version string `json:"version"`
	// Manufacturer of the mobile robot.
	Manufacturer string `json:"manufacturer"`
	// Serial number of the mobile robot.
	SerialNumber string `json:"serialNumber"`
	// ONLINE: connection between mobile robot and broker is active. OFFLINE: connection between mobile
	// robot and broker has gone offline in a coordinated way. HIBERNATING: connection between mobile
	// robot and broker is active, but mobile robot does not state messages. This mode is intended for
	// power-saving or communication reduction. The mobile robot can resume to ONLINE when instructed.
	// CONNECTION_BROKEN: The connection between mobile robot and broker has unexpectedly ended.
	ConnectionState ConnectionState `json:"connectionState"`
}

