// ZoneSet is the VDA5050 3.0.0 `zoneSet` object.
type ZoneSet struct {
	// Globally unique identifier of the map the zone set particularizes.
	MapID string `json:"mapId"`
	// Globally unique identifier of the zone set.
	ZoneSetID string `json:"zoneSetId"`
	// A user-defined, human-readable name or descriptor.
	// Optional.
	ZoneSetDescriptor *string `json:"zoneSetDescriptor,omitempty"`
	// Array of zone objects.
	Zones []Zone `json:"zones"`
}

// ZoneSetMessage Zone set detailing a dedicated map.
type ZoneSetMessage struct {
	// headerId of the message. The headerId is defined per topic and incremented by 1 with each sent
	// (but not necessarily received) message.
	HeaderID uint32 `json:"headerId"`
	// Timestamp in ISO8601 format (YYYY-MM-DDTHH:mm:ss.fffZ).
	Timestamp string `json:"timestamp"`
	// Version of the protocol [Major].[Minor].[Patch]
	Version string `json:"version"`
	// Manufacturer of the mobile robot.
	Manufacturer string `json:"manufacturer"`
	// Serial number of the mobile robot.
	SerialNumber string  `json:"serialNumber"`
	ZoneSet      ZoneSet `json:"zoneSet"`
}

// Response is the VDA5050 3.0.0 `response` object.
type Response struct {
	// Unique per mobile robot identifier within all active requests.
	RequestID string `json:"requestId"`
	// Enum {'GRANTED','QUEUED','REVOKED','REJECTED'}. 'GRANTED': fleet control grants request.
	// 'REVOKED': fleet control revokes previously granted request. 'REJECTED': fleet control rejects a
	// request. 'QUEUED': Acknowledge the mobile robot's request to the fleet control, but no
	// permission is given yet. Request was added to some sort of a queue.
	GrantType GrantType `json:"grantType"`
	// Timestamp (ISO 8601, UTC); YYYY-MM-DDTHH:mm:ss.fffZ (e.g., '2017-04-15T11:40:03.123Z').
	// Optional.
	LeaseExpiry *string `json:"leaseExpiry,omitempty"`
}

// Responses Responses from fleet control to mobile robot's requests.
type Responses struct {
	// Header ID of the message. The headerId is defined per topic and incremented by 1 with each sent
	// (but not necessarily received) message.
	HeaderID uint32 `json:"headerId"`
	// Timestamp (ISO 8601, UTC); YYYY-MM-DDTHH:mm:ss.fffZ (e.g., '2017-04-15T11:40:03.123Z').
	Timestamp string `json:"timestamp"`
	// Version of the protocol [Major].[Minor].[Patch]
	Version string `json:"version"`
	// Manufacturer of the mobile robot.
	Manufacturer string `json:"manufacturer"`
	// Serial number of the mobile robot.
	SerialNumber string `json:"serialNumber"`
	// Array of response objects.
	Responses []Response `json:"responses"`
}
